using AISmartLearning.API.Contracts;using AISmartLearning.API.Data;using AISmartLearning.API.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AISmartLearning.API.Controllers;
[ApiController][Authorize(Roles="Admin")][Route("api/admin")] public sealed class AdminController(AppDbContext db,InteractionLogService logs):ControllerBase {
[HttpGet("users")] public async Task<IActionResult> Users([FromQuery]string? search,[FromQuery]string? role,[FromQuery]int page=1,[FromQuery]int pageSize=20,CancellationToken ct=default){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Users.AsNoTracking().Include(x=>x.Role).AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search));if(!string.IsNullOrWhiteSpace(role))q=q.Where(x=>x.Role!.RoleName==role);var total=await q.CountAsync(ct);var items=await q.OrderBy(x=>x.UserId).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new UserSummary(x.UserId,x.FullName,x.Email,x.Role!.RoleName,x.IsActive)).ToListAsync(ct);return Ok(new{page,pageSize,total,items});}
[HttpPatch("users/{id:int}/status")] public async Task<IActionResult> Status(int id,SetUserStatusRequest r,CancellationToken ct){var actor=InteractionLogService.UserId(User);if(id==actor&&!r.IsActive)return BadRequest(new{message="You cannot deactivate your own account."});var u=await db.Users.SingleOrDefaultAsync(x=>x.UserId==id,ct);if(u is null)return NotFound();u.IsActive=r.IsActive;await db.SaveChangesAsync(ct);await logs.Write(actor,"UserStatusChanged",$"UserId={id}; IsActive={r.IsActive}",null,ct);return NoContent();}
[HttpGet("logs")] public async Task<IActionResult> Logs([FromQuery]string? search,[FromQuery]string? role,[FromQuery]int page=1,[FromQuery]int pageSize=25,CancellationToken ct=default){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.InteractionLogs.AsNoTracking().Include(x=>x.User).ThenInclude(x=>x!.Role).AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Action.Contains(search)||x.Details.Contains(search)||x.User!.Email.Contains(search)||x.User.FullName.Contains(search));if(!string.IsNullOrWhiteSpace(role))q=q.Where(x=>x.User!.Role!.RoleName==role);var total=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{ x.LogId,x.UserId,userName=x.User!.FullName,email=x.User.Email,roleName=x.User.Role!.RoleName,x.ConversationId,x.Action,x.Details,x.CreatedAt}).ToListAsync(ct);return Ok(new{page,pageSize,total,items});}
}